{"content":"from math import gcd


def encode(plain_text, a, b):
    """Encrypt Roman letters and digits, grouping the result by five."""
    if gcd(a, 26) != 1:
        raise ValueError("a and m must be coprime.")

    encoded = []
    for character in plain_text:
        if "A" <= character <= "Z" or "a" <= character <= "z":
            index = ord(character.lower()) - ord("a")
            encoded.append(chr((a * index + b) % 26 + ord("a")))
        elif "0" <= character <= "9":
            encoded.append(character)

    ciphertext = "".join(encoded)
    return " ".join(ciphertext[i:i + 5] for i in range(0, len(ciphertext), 5))


def decode(ciphered_text, a, b):
    """Decrypt Roman letters and digits, omitting spacing and punctuation."""
    if gcd(a, 26) != 1:
        raise ValueError("a and m must be coprime.")

    inverse = pow(a, -1, 26)
    decoded = []
    for character in ciphered_text:
        if "A" <= character <= "Z" or "a" <= character <= "z":
            index = ord(character.lower()) - ord("a")
            decoded.append(chr((inverse * (index - b)) % 26 + ord("a")))
        elif "0" <= character <= "9":
            decoded.append(character)

    return "".join(decoded)
