{"content":"import unittest
from math import gcd

from affine_cipher import decode, encode


class AffineCipherTests(unittest.TestCase):
    def test_examples(self):
        self.assertEqual(encode("test", 5, 7), "ybty")
        self.assertEqual(decode("ybty", 5, 7), "test")
        self.assertEqual(decode("ybty", 11, 7), "lqul")
        ciphertext = "kqlfd jzvgy tpaet icdhm rtwly kqlon ubstx"
        plaintext = "thequickbrownfoxjumpsoverthelazydog"
        self.assertEqual(decode(ciphertext, 19, 13), plaintext)
        self.assertEqual(encode(plaintext, 19, 13), ciphertext)

    def test_case_digits_and_punctuation(self):
        self.assertEqual(encode("TeSt, 123!", 5, 7), "ybty1 23")
        self.assertEqual(decode("YBTY1, 23!", 5, 7), "test123")

    def test_group_boundaries(self):
        for length, expected in [(4, "1234"), (5, "12345"),
                                 (6, "12345 6"), (10, "12345 67890")]:
            with self.subTest(length=length):
                self.assertEqual(encode("1234567890"[:length], 1, 0), expected)

    def test_empty_or_excluded_input(self):
        for function in (encode, decode):
            for text in ("", " ,.!\n\t", "éΩ١"):
                with self.subTest(function=function.__name__, text=text):
                    self.assertEqual(function(text, 1, 0), "")

    def test_invalid_keys_raise_with_required_message(self):
        for function in (encode, decode):
            for a in (0, 2, 13, 18, 26, -13):
                for text in ("test", ""):
                    with self.subTest(function=function.__name__, a=a, text=text):
                        with self.assertRaisesRegex(ValueError, r"^a and m must be coprime\.$"):
                            function(text, a, 13)

    def test_round_trip_with_all_coprime_residues_and_integer_keys(self):
        plaintext = "abcdefghijklmnopqrstuvwxyz0123456789"
        for a in range(-53, 54):
            if gcd(a, 26) != 1:
                continue
            for b in (-100, -1, 0, 7, 26, 100):
                with self.subTest(a=a, b=b):
                    self.assertEqual(decode(encode(plaintext, a, b), a, b), plaintext)


if __name__ == "__main__":
    unittest.main()
